// Safety cap: prevents a single run from processing an unbounded number of rows.
const MAX_LEADS_PER_RUN = 5000;

// Statuses already set by Workflow B or C. If a lead is in one of these,
// Workflow A leaves Status alone on re-run — this is what makes it safe to
// re-run A later (e.g. weekly, to segment newly-added leads) without undoing
// progress on leads already in the middle of a conversation.
const LOCKED_STATUSES = new Set([
  'contacted',
  'Hot Lead - Needs Human Follow-Up',
  'Not Interested - Dead',
  'Do Not Contact',
  'suppressed'
]);

// Split the merged 133 items back into two groups using a column that only
// exists on one sheet — no artificial tagging needed, so nothing can silently
// fail to apply the tag.
const suppressionItems = items
  .filter(i => i.json['Suppression Reason'] !== undefined)
  .map(i => i.json);

let leadItems = items
  .filter(i => i.json['Suppression Reason'] === undefined)
  .map(i => i.json);

const suppressedEmails = new Set(suppressionItems.map(s => (s.Email || '').toLowerCase().trim()));
const suppressedPhones = new Set(suppressionItems.map(s => (s['Phone Number'] || '').replace(/\D/g, '')));

if (leadItems.length > MAX_LEADS_PER_RUN) {
  leadItems = leadItems.slice(0, MAX_LEADS_PER_RUN);
}

return leadItems.map(lead => {
  const email = (lead.Email || '').toLowerCase().trim();
  const phoneDigits = (lead['Phone Number'] || '').replace(/\D/g, '');
  const isSuppressed = suppressedEmails.has(email) || suppressedPhones.has(phoneDigits);

  const daysSince = Number(lead['Days Since Last Activity']) || 0;
  let segment = 'Recent (0-6mo)';
  if (daysSince > 365) segment = 'Old (12-24mo)';
  else if (daysSince > 180) segment = 'Mid (6-12mo)';

  const dealValue = Number(lead['Estimated Deal Value']) || 0;
  const priority = dealValue >= 15000 ? 'High' : dealValue >= 6000 ? 'Medium' : 'Low';

  const smsOk = lead['SMS Opt-In'] === 'Yes';
  const emailOk = lead['Email Opt-In'] === 'Yes';

  const currentStatus = lead['Status'] || '';
  let status;

  if (LOCKED_STATUSES.has(currentStatus)) {
    status = currentStatus; // already in progress elsewhere — don't touch it
  } else if (isSuppressed) {
    status = 'suppressed';
  } else if (!smsOk && !emailOk) {
    status = 'no_consent_hold';
  } else {
    status = 'ready_for_outreach';
  }

  return {
    json: {
      ...lead,
      'Segment': segment,
      'Priority': priority,
      'Status': status
    }
  };
});
